inline void interpolateCubic( float x, float* coeffs )
{
const float A = -0.75f;
coeffs[0] = fma(fma(fma(A, (x + 1.f), - 5.0f*A), (x + 1.f), 8.0f*A), x + 1.f, - 4.0f*A);
