ny = M[3] * convert_float4((vec_offset + (short4)x)) + M[4] * convert_float4((short4)y) + M[5];
int4 ax, ay;
ax = convert_int4_sat_rte((nx - floor(nx)) * 32.0f) & 31;
ay = convert_int4_sat_rte((ny - floor(ny)) * 32.0f) & 31;
